mapper.select:
SELECT el.*,
       ou.username AS owner_name,
       COALESCE(eu.username, uu.username) AS executor_name
FROM execution_log el
LEFT JOIN user ou ON ou.id = el.owner_id
LEFT JOIN user eu ON eu.id = el.executor_id
LEFT JOIN user uu ON uu.id = el.user_id


        AND el.flow_name LIKE CONCAT('%', #{flowName}, '%')


        AND el.execute_type = #{executeType}


        AND el.status = #{status}


        AND el.source = #{source}


        AND el.owner_id = #{ownerId}


        AND el.executor_id = #{executorId}


        AND el.start_time >= #{startTime}


        AND el.start_time <= #{endTime}



        AND el.user_id = #{filterUserId}


ORDER BY el.id DESC
